function documentTool(d){return {name:d.title,url:'/OCCtools/documents/'+d.id+'.pdf',display:'pdf',page:d.page||1,addedAt:d.addedAt};}
async function renderDocumentsAdmin(area){
 area.append(el('h3','','PDF-dokumenter'),el('p','notice','Upload gemmes med det samme i PDF-biblioteket. Ved udskiftning bevares linket og en backup. Nye menupunkter udgives med “Gem ændringer” nederst. Maks. 25 MB pr. PDF.'));
 const mode=field('Handling','','select');for(const [v,n] of [['new','Nyt punkt med PDF'],['replace','Udskift eksisterende PDF']]){const o=el('option','',n);o.value=v;mode.input.append(o);}
 const existing=field('Eksisterende dokument','','select'),search=field('Find dokument','','search'),title=field('Navn på nyt PDF-punkt','','text'),folder=field('Mappe i bibliotek (valgfrit)','','text');
 const menu=field('Menu til nyt punkt','','select');for(const g of draft.categories.filter(g=>g.id!=='flightpoint')){const o=el('option','',g.name);o.value=g.id;menu.input.append(o);}menu.input.value='procedures';
 const file=field('Vælg PDF','','file');file.input.accept='.pdf,application/pdf';const drop=el('div','pdfDropzone','Træk én PDF hertil, eller vælg fil nedenfor.');drop.append(file.label);const state=el('p','muted');state.setAttribute('role','status');const save=button('Upload PDF','primary',upload);let chosen=null,docs=[],busy=false;
 area.append(mode.label,search.label,existing.label,title.label,menu.label,folder.label,drop,state,save);
 function choose(f){if(!f)return;if(!f.name.toLowerCase().endsWith('.pdf')||f.size>25*1024*1024){chosen=null;state.textContent='Vælg en PDF på højst 25 MB.';return;}chosen=f;if(!title.input.value)title.input.value=f.name.replace(/\.pdf$/i,'');state.textContent=f.name+' · '+(f.size/1024/1024).toFixed(1)+' MB';}
 file.input.onchange=()=>choose(file.input.files[0]);drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragOver');};drop.ondragleave=()=>drop.classList.remove('dragOver');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragOver');if(!busy){if(e.dataTransfer.files.length!==1){state.textContent='Træk én PDF ad gangen.';return;}choose(e.dataTransfer.files[0]);}};
 function filter(){const previous=existing.input.value;existing.input.replaceChildren();for(const d of docs.filter(d=>d.title.toLocaleLowerCase('da').includes(search.input.value.toLocaleLowerCase('da')))){const o=el('option','',d.title+(d.folder?' · '+d.folder:''));o.value=d.id;existing.input.append(o);}if([...existing.input.options].some(o=>o.value===previous))existing.input.value=previous;}
 function toggle(){const replacing=mode.input.value==='replace';search.label.hidden=existing.label.hidden=!replacing;title.label.hidden=menu.label.hidden=folder.label.hidden=replacing;save.textContent=replacing?'Udskift PDF og gem backup':'Upload PDF og tilføj punkt';}mode.input.onchange=toggle;search.input.oninput=filter;toggle();
 try{docs=(await api('documents')).items.sort((a,b)=>a.title.localeCompare(b.title,'da'));filter();}catch{state.textContent='Dokumentlisten kunne ikke hentes.';}
 async function upload(){if(busy)return;if(!chosen){state.textContent='Vælg en PDF først.';return;}const replacing=mode.input.value==='replace',old=docs.find(d=>d.id===existing.input.value),g=draft.categories.find(g=>g.id===menu.input.value);if(replacing&&!old){state.textContent='Vælg dokumentet, der skal udskiftes.';return;}if(!replacing&&(!title.input.value.trim()||!g||g.tools.length>=100)){state.textContent='Udfyld navn og vælg en menu med plads til et nyt punkt.';return;}if(replacing&&!confirm('Udskift “'+old.title+'”? Den tidligere PDF bevares som backup.'))return;
 busy=true;save.disabled=true;state.textContent='Uploader og opdaterer søgningen…';try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(chosen);});const result=await api('documents',{method:'POST',body:JSON.stringify({id:replacing?old.id:undefined,version:old?.version||'',title:title.input.value.trim(),category:g?.id==='crew'?'transport-docs':g?.id,folder:folder.input.value.trim(),base64})});if(!replacing)g.tools.push({id:uid(),name:result.title,url:result.url,display:'pdf',description:'Lokal PDF-kopi. Kontrollér gældende version.',manual:''});docs=docs.filter(d=>d.id!==result.id).concat(result).sort((a,b)=>a.title.localeCompare(b.title,'da'));filter();chosen=null;file.input.value='';state.textContent=(replacing?'PDF udskiftet. Linket er bevaret, og backup er gemt.':'PDF uploadet. Tryk “Gem ændringer” nederst for at udgive menupunktet.')+(result.searchablePages?'':' Dokumentet er scannet; kun titlen kan søges.');}catch(e){state.textContent=e.message||'Upload mislykkedes. Prøv igen.';}finally{busy=false;save.disabled=false;}}
}
async function openLocalPdf(t){
 let panel=$('#pdfViewer');if(!panel){panel=el('dialog','pdfViewer');panel.id='pdfViewer';document.body.append(panel);panel.addEventListener('close',()=>panel.replaceChildren());}
 panel.replaceChildren();const top=el('div','dialogTop'),heading=el('h2','',t.name),close=button('×','close',()=>panel.close());heading.id='pdfViewerTitle';close.setAttribute('aria-label','Luk PDF');top.append(heading,close);panel.setAttribute('aria-labelledby','pdfViewerTitle');
 const id=t.url.split('/').pop().replace('.pdf',''),notice=el('p','muted','Lokal kopi – kontrollér gældende version i Comply365.'),status=el('p','muted','Henter dokument…'),pages=el('div','pdfPages'),image=el('img');image.alt=t.name;pages.append(image);
 const controls=el('div','pdfControls'),pageInput=el('input'),count=el('span'),previous=button('←','quiet',()=>showPage(current-1)),next=button('→','quiet',()=>showPage(current+1));previous.setAttribute('aria-label','Forrige PDF-side');next.setAttribute('aria-label','Næste PDF-side');pageInput.type='number';pageInput.min='1';pageInput.setAttribute('aria-label','PDF-sidetal');controls.append(previous,pageInput,count,next,link('Åbn PDF i nyt vindue ↗',t.url,'quiet'));
 let zoom=100;const zoomOut=button('−','quiet',()=>adjustZoom(-25)),zoomIn=button('+','quiet',()=>adjustZoom(25));zoomOut.setAttribute('aria-label','Formindsk PDF');zoomIn.setAttribute('aria-label','Forstør PDF');controls.append(zoomOut,zoomIn);function adjustZoom(change){zoom=Math.max(100,Math.min(250,zoom+change));image.className='pdfZoom'+zoom;zoomOut.disabled=zoom===100;zoomIn.disabled=zoom===250;}zoomOut.disabled=true;
 panel.append(top,notice,controls,documentPdfSearch(t,page=>showPage(page)),status,pages);if(!panel.open)panel.showModal();let current=1,total=1;
 function showPage(n){if(!Number.isInteger(n)||n<1||n>total){pageInput.value=current;return;}current=n;pageInput.value=n;previous.disabled=n===1;next.disabled=n===total;status.textContent='Henter side '+n+'…';image.hidden=true;image.onload=()=>{status.textContent='';image.hidden=false;};image.onerror=()=>{status.textContent='Forhåndsvisningen kunne ikke hentes. Brug “Åbn PDF i nyt vindue”.';};image.src='/OCCtools/document-preview/'+id+'/'+n+'.png';pages.scrollTop=0;}
 pageInput.onchange=()=>showPage(Number(pageInput.value));
 try{const r=await api('documents?id='+encodeURIComponent(id));if(!heading.isConnected)return;const d=r.items[0];if(!d)throw new Error();total=d.pageCount;pageInput.max=String(total);count.textContent='af '+total;notice.textContent+=' Tilføjet '+new Date(d.addedAt).toLocaleDateString('da-DK')+' (ikke revisionsdato).'+(d.searchablePages<total?' Nogle sider er scannede og kan ikke tekstsøges.':'');showPage(Math.min(total,t.page||1));}catch{status.textContent='Dokumentet kunne ikke hentes.';}
}
function documentMenuNames(d){
 const names=data.categories.filter(g=>g.tools.some(t=>t.url==='/OCCtools/documents/'+d.id+'.pdf')).map(g=>g.name);
 if(!names.length){const category=d.category==='transport-docs'?'crew':d.category;const g=data.categories.find(g=>g.id===category);names.push(g?.name||({'transport-docs':'Transport og hoteller','union-agreements':'Overenskomster',procedures:'Træning og manualer'}[d.category])||'PDF-bibliotek');}
 return names.join(', ');
}
function documentCard(d){
 const b=button('','searchResult',()=>openPdf(documentTool(d)));
 b.append(el('strong','',d.title),el('small','muted','Menu: '+documentMenuNames(d)),el('small','muted',(d.folder?d.folder+' · ':'')+(d.page?'side '+d.page:d.pageCount+' sider')+(d.searchablePages<d.pageCount?' · helt/delvist scannet':'')));
 if(d.snippet)b.append(el('span','documentSnippet',d.snippet));return b;
}
async function openDocumentLibrary(category){
 let dialog=$('#documentLibrary');if(!dialog){dialog=el('dialog','documentLibrary');dialog.id='documentLibrary';document.body.append(dialog);}
 dialog.replaceChildren();const top=el('div','dialogTop');top.append(el('h2','',category==='procedures'?'Procedurer og manualer':category==='transport-docs'?'Transportdokumenter':'Overenskomster'),button('×','close',()=>dialog.close()));top.lastChild.setAttribute('aria-label','Luk dokumentbibliotek');
 const q=el('input');q.type='search';q.placeholder='Søg i dokumenternes titler og indhold';q.setAttribute('aria-label','Søg i PDF-bibliotek');const folders=el('select');folders.setAttribute('aria-label','Proceduremappe');const state=el('p','muted'),list=el('div','documentGrid');
 dialog.append(top,el('p','notice','Lokale kopier – kontrollér gældende version i Comply365. Tilføjelsesdato er ikke revisionsdato.'),q,folders,state,list);dialog.showModal();let generation=0;
 try{const r=await api('documents?category='+encodeURIComponent(category));const names=[...new Set(r.items.flatMap(d=>[d.folder,...(d.alsoIn||[])]).filter(Boolean))].sort();for(const name of ['Alle mapper',...names]){const option=el('option','',name);option.value=name==='Alle mapper'?'':name;folders.append(option);}folders.hidden=names.length<2;}catch{state.textContent='Dokumentbiblioteket kunne ikke hentes.';return;}
 async function search(){const gen=++generation;state.textContent='Søger…';try{const r=await api('documents?category='+encodeURIComponent(category)+'&folder='+encodeURIComponent(folders.value)+'&q='+encodeURIComponent(q.value.trim()));if(gen!==generation||!dialog.open)return;list.replaceChildren(...r.items.map(documentCard));state.textContent=r.total+' resultater'+(r.total>r.items.length?' · viser de første 60, afgræns søgningen':'');}catch{if(gen===generation)state.textContent='Søgningen kunne ikke gennemføres.';}}
 q.oninput=search;folders.onchange=search;await search();
}
function documentPdfSearch(t,frame){const row=el('div','pdfTextSearch'),q=el('input'),results=el('div','pdfTextResults');q.type='search';q.placeholder='Søg i dette dokument';q.setAttribute('aria-label','Søg i dette PDF-dokument');row.append(q,results);let timer,seq=0;const id=t.url.split('/').pop().replace('.pdf','');
 q.oninput=()=>{clearTimeout(timer);const current=++seq;results.replaceChildren();if(!q.value.trim())return;timer=setTimeout(async()=>{try{const r=await api('documents?id='+encodeURIComponent(id)+'&q='+encodeURIComponent(q.value.trim()));if(current!==seq)return;for(const d of r.items){const b=button('Side '+d.page+' · '+d.snippet,'quiet',()=>{if(typeof frame==='function')frame(d.page);else frame.src=t.url+'#page='+d.page;});results.append(b);}if(!r.items.length)results.append(el('span','muted','Ingen tekstmatch. Scannede sider kræver OCR.'));}catch{results.textContent='Søgning er ikke tilgængelig.';}},250);};return row;}
let documentSearchTimer,documentSearchGeneration=0;
document.addEventListener('input',e=>{if(e.target.id!=='portalSearchInput')return;clearTimeout(documentSearchTimer);const input=e.target,q=input.value.trim(),gen=++documentSearchGeneration;let host=$('#pdfGlobalResults');if(!host){host=el('section');host.id='pdfGlobalResults';input.closest('.portalSearch').append(host);}host.replaceChildren();if(q.length<2)return;
 documentSearchTimer=setTimeout(async()=>{
  try{
   const r=await api('documents?q='+encodeURIComponent(q));if(gen!==documentSearchGeneration||!input.isConnected)return;
   host.className='searchGroup pdfSearchGroup';host.append(el('h3','','PDF-indhold · '+r.total+' sidematch'));
   const list=el('div','groupResultGrid'),more=button('Vis flere PDF-resultater','quiet',()=>draw(visible+6));let visible=0;
   function draw(count){visible=Math.min(count,r.items.length);list.replaceChildren(...r.items.slice(0,visible).map(documentCard));more.hidden=visible>=r.items.length;more.textContent='Vis flere PDF-resultater ('+visible+' af '+r.items.length+')';}
   draw(6);host.append(list,more);
   if(!r.items.length)host.append(el('p','muted','Ingen match i PDF-indhold.'));
   if(r.total>r.items.length)host.append(el('p','muted','Op til 60 sidematch vises. Afgræns søgningen for flere relevante resultater.'));
  }catch{if(gen===documentSearchGeneration&&input.isConnected)host.append(el('p','error','PDF-søgningen kunne ikke hentes.'));}
 },250);
});
